WITH lines AS (SELECT id, customer_id, created_at, key, value FROM carts LATERAL VIEW EXPLODE(attributes) t AS key, value), valid AS (SELECT id, customer_id, created_at, key, value, COALESCE(key, 'Unknown') AS key_filled, COALESCE(key, 'NONE') AS key_filled_2 FROM lines WHERE created_at >= DATE '2025-03-01' AND key IS DISTINCT FROM 'device'), ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY created_at DESC, id, key) AS rn FROM valid) ranked WHERE rn = 1), latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY customer_id, key ORDER BY created_at, id, key) AS row_num FROM ranked) x WHERE row_num = 1), enriched AS (SELECT s.id, s.customer_id, s.key, s.value, s.key_filled_2, c.segment, c.city FROM latest s LEFT JOIN customers c ON s.customer_id = c.id) SELECT segment, city, COUNT_IF(city = 'Singapore') AS singapore_events, COUNT(*) AS event_count, COUNT(CASE WHEN key = 'utm_source' THEN 1 END) AS utm_source_count, COUNT(CASE WHEN key = 'utm_source' THEN 1 END) AS utm_source_count_2, GROUPING_ID() AS grouping_level FROM enriched GROUP BY ROLLUP (segment, city) HAVING COUNT(CASE WHEN key = 'utm_source' THEN 1 END) > 1;
